<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/idempotency.php';send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->prepare('SELECT a.*,e.title,e.starts_at,e.venue_name FROM event_vendor_applications a JOIN events e ON e.id=a.event_id WHERE a.vendor_id=:vendor ORDER BY a.submitted_at DESC');$stmt->execute(['vendor'=>$vendorId]);json_response(200,['success'=>true,'applications'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$eventId=trim((string)($body['event_id']??''));$text=trim((string)($body['application_text']??''));$requirements=trim((string)($body['stall_requirements']??''));if(mb_strlen($text)<40||mb_strlen($text)>3000)json_response(422,['success'=>false,'message'=>'Tell the event team what you will exhibit.']);$event=$db->prepare('SELECT id FROM events WHERE id=:id AND status="published" AND starts_at>UTC_TIMESTAMP()');$event->execute(['id'=>$eventId]);if(!$event->fetch())json_response(404,['success'=>false,'message'=>'Event is not accepting applications.']);$idem=begin_idempotent_request('event.vendor_apply',['type'=>'vendor','id'=>$vendorId],$body);$id=uuid_string();try{$db->prepare('INSERT INTO event_vendor_applications (id,event_id,vendor_id,application_text,stall_requirements,status,fee_amount,payment_status,submitted_at,updated_at) VALUES (:id,:event,:vendor,:text,:requirements,"submitted",0,"not_required",UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$id,'event'=>$eventId,'vendor'=>$vendorId,'text'=>$text,'requirements'=>$requirements?:null]);}catch(PDOException $e){if((string)$e->getCode()==='23000')json_response(409,['success'=>false,'message'=>'You already applied to this event.']);throw $e;}$response=['success'=>true,'message'=>'Event application submitted.','application_id'=>$id];finish_idempotent_request((int)$idem['id'],201,$response);json_response(201,$response);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
